"""Durable at-least-once, per-consumer local event delivery.

Only trusted Core code may register handlers. A handler participates in the same
SQLite transaction and must not perform external side effects.
"""

import json
import math
import re
import secrets
import time
from dataclasses import asdict

from .agent_protocol import COORDINATION_EVENTS, AgentMessage
from .domain import DomainError
from .event_domain import URGENT_EVENTS, WORKER_COMMANDS, WORKER_FACTS, DeliveryLease, EventEnvelope

_URGENT_PLACEHOLDERS = ",".join("?" for _ in URGENT_EVENTS)


class LeaseError(RuntimeError):
    pass


class Dispatcher:
    def __init__(
        self, store, *, clock=time.time, lease_seconds=30, max_attempts=5, base_backoff_seconds=1
    ):
        if type(max_attempts) is not int or not 1 <= max_attempts <= 100:
            raise ValueError("Invalid delivery attempts")
        if any(
            type(x) not in (float, int) or not math.isfinite(x) or x <= 0
            for x in (lease_seconds, base_backoff_seconds)
        ):
            raise ValueError("Invalid delivery timing")
        self.store, self.clock = store, clock
        self.lease_seconds, self.max_attempts, self.base_backoff_seconds = (
            lease_seconds,
            max_attempts,
            base_backoff_seconds,
        )
        self._worker_cursor = ""
        self._consumer_cursor = 0

    def _now(self):
        now = self.clock()
        if type(now) not in (float, int) or not math.isfinite(now):
            raise ValueError("Invalid clock value")
        return float(now)

    def register(self, consumer_id, *, kind="router", worker_id=None, replay_from_seq=0):
        if (
            not isinstance(consumer_id, str)
            or not consumer_id
            or len(consumer_id) > 256
            or type(replay_from_seq) is not int
            or replay_from_seq < 0
        ):
            raise ValueError("Invalid consumer")
        if (
            kind not in {"router", "worker"}
            or (kind == "router" and worker_id is not None)
            or (kind == "worker" and (not isinstance(worker_id, str) or not worker_id))
        ):
            raise ValueError("Invalid consumer kind")
        with self.store.unit_of_work() as work:
            connection = work.connection
            old = connection.execute(
                "SELECT * FROM event_consumers WHERE id=?", (consumer_id,)
            ).fetchone()
            if old is not None:
                if (old["kind"], old["worker_id"], old["replay_from_seq"]) != (
                    kind,
                    worker_id,
                    replay_from_seq,
                ):
                    raise ValueError("Consumer registration differs from existing subscription")
                return
            connection.execute(
                "INSERT INTO event_consumers VALUES (?,?,?,?,?,?,?)",
                (
                    consumer_id,
                    kind,
                    worker_id,
                    replay_from_seq,
                    replay_from_seq,
                    replay_from_seq,
                    replay_from_seq,
                ),
            )

    @staticmethod
    def _materialize(connection, consumer_id):
        consumer = connection.execute(
            "SELECT scan_seq,priority_scan_seq FROM event_consumers WHERE id=?", (consumer_id,)
        ).fetchone()
        rows = connection.execute(
            "SELECT id,seq FROM events WHERE seq>? ORDER BY seq LIMIT 100", (consumer["scan_seq"],)
        ).fetchall()
        connection.executemany(
            "INSERT OR IGNORE INTO event_deliveries(consumer_id,event_id,seq,state) VALUES (?,?,?,'pending')",
            [(consumer_id, row["id"], row["seq"]) for row in rows],
        )
        if rows:
            connection.execute(
                "UPDATE event_consumers SET scan_seq=? WHERE id=?", (rows[-1]["seq"], consumer_id)
            )
        urgent = connection.execute(
            f"""SELECT e.id,e.seq FROM events e WHERE e.seq>? AND e.event_type IN
            ({_URGENT_PLACEHOLDERS}) ORDER BY e.seq LIMIT 16""",
            (consumer["priority_scan_seq"], *URGENT_EVENTS),
        ).fetchall()
        connection.executemany(
            "INSERT OR IGNORE INTO event_deliveries(consumer_id,event_id,seq,state) VALUES (?,?,?,'pending')",
            [(consumer_id, row["id"], row["seq"]) for row in urgent],
        )
        if urgent:
            connection.execute(
                "UPDATE event_consumers SET priority_scan_seq=? WHERE id=?",
                (urgent[-1]["seq"], consumer_id),
            )

    @staticmethod
    def _advance(connection, consumer_id, seq):
        scan = connection.execute(
            "SELECT scan_seq FROM event_consumers WHERE id=?", (consumer_id,)
        ).fetchone()[0]
        gap = connection.execute(
            "SELECT MIN(seq) FROM event_deliveries WHERE consumer_id=? AND state IN ('pending','leased')",
            (consumer_id,),
        ).fetchone()[0]
        if gap is None:
            last = connection.execute(
                "SELECT MAX(seq) FROM event_deliveries WHERE consumer_id=?", (consumer_id,)
            ).fetchone()[0]
        else:
            last = connection.execute(
                "SELECT MAX(seq) FROM event_deliveries WHERE consumer_id=? AND seq<? AND state IN ('delivered','dead','skipped')",
                (consumer_id, gap),
            ).fetchone()[0]
        if last is not None:
            connection.execute(
                "UPDATE event_consumers SET cursor_seq=MAX(cursor_seq,?) WHERE id=?",
                (min(last, scan), consumer_id),
            )

    @staticmethod
    def _routable(connection, consumer, row):
        is_command = row["event_type"].startswith("worker.command.")
        if consumer["id"] == "planner" and consumer["kind"] == "router":
            return row["event_type"] in {
                "quest.proposed",
                "quest.proposal_updated",
                "quest.replan_requested",
            }
        if consumer["id"] == "composer" and consumer["kind"] == "router":
            return row["event_type"] in {"quest.plan_approved", "worker.help_requested"}
        if consumer["kind"] == "worker":
            worker = connection.execute(
                "SELECT status FROM workers WHERE id=?", (consumer["worker_id"],)
            ).fetchone()
            return bool(
                worker
                and worker["status"] not in {"completed", "failed", "cancelled", "rejected"}
                and row["event_type"] in WORKER_COMMANDS
                and row["worker_id"] == consumer["worker_id"]
            )
        return not is_command

    def claim(self, consumer_id):
        with self.store.unit_of_work() as work:
            now = self._now()
            connection = work.connection
            consumer = connection.execute(
                "SELECT * FROM event_consumers WHERE id=?", (consumer_id,)
            ).fetchone()
            if consumer is None:
                raise KeyError(consumer_id)
            self._materialize(connection, consumer_id)
            while True:
                row = connection.execute(
                    """SELECT d.*,e.event_type,e.worker_id FROM event_deliveries d
                    JOIN events e ON e.id=d.event_id WHERE d.consumer_id=? AND d.state IN ('pending','leased')
                    ORDER BY d.seq LIMIT 1""",
                    (consumer_id,),
                ).fetchone()
                if row is None:
                    return None
                urgent = connection.execute(
                    f"""SELECT d.*,e.event_type,e.worker_id FROM event_deliveries d
                    JOIN events e ON e.id=d.event_id WHERE d.consumer_id=?
                    AND e.event_type IN ({_URGENT_PLACEHOLDERS})
                    AND ((d.state='pending' AND d.next_attempt<=?) OR (d.state='leased' AND d.lease_until<=?))
                    ORDER BY d.seq LIMIT 1""",
                    (consumer_id, *URGENT_EVENTS, now, now),
                ).fetchone()
                if urgent is not None:
                    row = urgent
                if not self._routable(connection, consumer, row):
                    connection.execute(
                        "UPDATE event_deliveries SET state='skipped' WHERE consumer_id=? AND event_id=?",
                        (consumer_id, row["event_id"]),
                    )
                    self._advance(connection, consumer_id, row["seq"])
                    continue
                if row["state"] == "leased" and row["lease_until"] > now:
                    return None
                if row["state"] == "pending" and row["next_attempt"] > now:
                    return None
                if row["attempts"] >= self.max_attempts:
                    connection.execute(
                        "UPDATE event_deliveries SET state='dead',lease_token=NULL,lease_until=NULL,last_error='lease_expired' WHERE consumer_id=? AND event_id=?",
                        (consumer_id, row["event_id"]),
                    )
                    self._advance(connection, consumer_id, row["seq"])
                    continue
                token = secrets.token_hex(32)
                attempt = row["attempts"] + 1
                connection.execute(
                    "UPDATE event_deliveries SET state='leased',lease_token=REDACTED,lease_until=?,attempts=? WHERE consumer_id=? AND event_id=?",
                    (token, now + self.lease_seconds, attempt, consumer_id, row["event_id"]),
                )
                return DeliveryLease(consumer_id, row["event_id"], row["seq"], token, attempt)

    def _leased(self, connection, lease, now):
        if not isinstance(lease, DeliveryLease):
            raise LeaseError("Invalid delivery lease")
        row = connection.execute(
            """SELECT d.*,e.event_type,e.conversation_id,e.quest_id,e.worker_id,e.payload
            FROM event_deliveries d JOIN events e ON e.id=d.event_id
            WHERE d.consumer_id=? AND d.event_id=?""",
            (lease.consumer_id, lease.event_id),
        ).fetchone()
        if (
            row is None
            or row["state"] != "leased"
            or row["lease_token"] != lease.token
            or row["lease_until"] <= now
            or row["seq"] != lease.seq
            or row["attempts"] != lease.attempt
        ):
            raise LeaseError("Delivery lease is stale")
        return row

    @staticmethod

                connection.execute(
                    "UPDATE event_inbox SET notice_attempts=notice_attempts+1,notice_next_attempt=?,notice_token=REDACTED WHERE consumer_id='router' AND event_id=?",
                    (time.time() + 60, notice_token, event_id),
                )
        try:
            import asyncio

            return await asyncio.wait_for(self._handle_notice(event_ids, notice_token), timeout=45)
        except Exception as exc:  # noqa: BLE001 - store a non-sensitive bounded failure code
            from .providers import ProviderError

            busy = isinstance(exc, ProviderError) and exc.code == "concurrency_unavailable"
            with self.store.unit_of_work() as work:
                for event_id in event_ids:
                    current = work.connection.execute(
                        "SELECT notice_attempts FROM event_inbox WHERE consumer_id='router' AND event_id=? AND processed_at IS NULL AND notice_dead_at IS NULL AND notice_token=REDACTED AND notice_next_attempt>?",
                        (event_id, notice_token, time.time()),
                    ).fetchone()
                    if current is not None:
                        attempts = (
                            max(0, current["notice_attempts"] - 1)
                            if busy
                            else current["notice_attempts"]
                        )
                        work.connection.execute(
                            "UPDATE event_inbox SET notice_attempts=?,notice_next_attempt=?,notice_error=?,notice_dead_at=?,notice_token=NULL WHERE consumer_id='router' AND event_id=? AND processed_at IS NULL AND notice_token=REDACTED,
                            (
                                attempts,
                                time.time() + (1 if busy else min(2 ** (attempts - 1), 60)),
                                "resource_busy" if busy else "processing_failed",
                                now_iso() if not busy and attempts >= 5 else None,
                                event_id,
                                notice_token,
                            ),
                        )
            return False

    async def _handle_notice(self, event_ids, notice_token):
        event_id = event_ids[0]
        with self.store.connection() as connection:
            connection.execute("BEGIN")
            notice = connection.execute(
                "SELECT * FROM event_inbox WHERE consumer_id='router' AND event_id=? AND processed_at IS NULL AND notice_dead_at IS NULL AND notice_token=REDACTED AND notice_next_attempt>?",
                (event_id, notice_token, time.time()),
            ).fetchone()
            if notice is None:
                return False
            notice = dict(notice)
            grouped = []
            for item_id in event_ids:
                item = connection.execute(
                    "SELECT * FROM event_inbox WHERE consumer_id='router' AND event_id=? AND processed_at IS NULL AND notice_dead_at IS NULL AND notice_token=REDACTED AND notice_next_attempt>?",
                    (item_id, notice_token, time.time()),
                ).fetchone()
                if item is None:
                    return False
                grouped.append(dict(item))
            snapshot = self._snapshot(connection, notice["quest_id"] or "")
            from .adaptive_planning import remaining_replan_context

            adaptive_plan = remaining_replan_context(
                self.store, connection, notice["quest_id"], notice["event_id"]
            )
            result_summaries = []
            if any(
                item["event_type"] == "quest.status_changed"
                and json.loads(item["payload"]).get("to") == "completed"
                for item in grouped
            ):
                for result in connection.execute(
                    "SELECT id,payload FROM events WHERE quest_id=? AND event_type='worker.result' ORDER BY seq DESC LIMIT 8",
                    (notice["quest_id"],),
                ):
                    try:
                        delivery = json.loads(json.loads(result["payload"])["claim"])
                    except (ValueError, KeyError, TypeError):
                        continue
                    result_summaries.append(
                        {
                            "source_event_id": result["id"],
                            "summary": str(delivery.get("summary", ""))[:1000],
                            "findings": [
                                str(item)[:400] for item in delivery.get("findings", [])[:3]
                            ],
                            "artifacts": delivery.get("artifacts", [])[:8],
                        }
                    )
            connection.commit()
        compactions = 0
        while (
            len(_json(snapshot["messages"]).encode("utf-8"))
            > self.effective_context_limit(self._model_profile(snapshot)) // 2
            or len(snapshot["messages"]) > 50
        ) and len(snapshot["messages"]) > 10:
            if compactions >= 100:
                raise DomainError("Router compaction backlog exceeds per-call limit")
            self.context_service.compact_router(keep_recent=10)
            compactions += 1
            with self.store.connection() as connection:
                connection.execute("BEGIN")
                snapshot = self._snapshot(connection, notice["quest_id"] or "")
                connection.commit()
        profile = self._model_profile(snapshot)
        mode = getattr(self.provider, "execution_mode", None)
        if mode != "mock" and (
            profile is None
            or not profile.enabled
            or profile.structured_output_support is None
            or not profile.structured_output_support.supported
        ):
            raise DomainError("Router model capability is unknown or unsupported")
        context, _ = self._context(snapshot, "Process the supplied background event.")
        # A notice coordinates one observed change. Replaying the complete
        # event/evidence backlog on every tool step consumes the Quest budget
        # without adding authority or new observations. Originals remain in the
        # durable event log and source-indexed context for explicit recall.
        context["events"] = []
        context["evidence"] = []
        context["memory"] = []
        context["recent_messages"] = []
        context["capsule"], context["capsule_truncated"] = _bounded_capsule(
            context["capsule"], 1600
        )
        projected = []
        for event in grouped:
            payload = json.loads(event["payload"])
            selected = {
                key: payload[key]
                for key in (
                    "plan_id",
                    "run_id",
                    "task_node_key",
                    "reason_code",
                    "failure_category",
                    "phase",
                    "verdict",
                    "from",
                    "to",
                    "status",
                    "receipt_id",
                    "token_spent",
                    "tool_calls",
                )
                if key in payload
            }
            projected.append(
                {
                    "event_id": event["event_id"],
                    "event_type": event["event_type"],
                    "seq": event["seq"],
                    "quest_id": event["quest_id"],
                    "worker_id": event["worker_id"],
                    "payload": selected,
                }
            )
        context["notice"] = {
            "events": projected,
            "source_event_ids": event_ids,
            "source_seq_min": min(item["seq"] for item in grouped),
            "source_seq_max": max(item["seq"] for item in grouped),
            "completed_delivery_summaries": result_summaries,
        }
        if adaptive_plan:
            context["notice"]["remaining_planning_available"] = adaptive_plan
        coordination = []
        for item in grouped:
            payload = json.loads(item["payload"])
            if payload.get("run_id"):
                message = AgentMessage.from_event({**item, "id": item["event_id"]}, payload)
                if message is not None:
                    coordination.append(
                        {
                            "message_id": message.message_id,
                            "message_type": message.message_type.value,
                            "sender_id": message.sender_id,
                            "receiver_id": message.receiver_id,
                            "correlation_id": message.correlation_id,
                        }
                    )
        if coordination:
            context["notice"]["coordination"] = coordination
        context["budget"]["notice_projection"] = True
        context["budget"]["input_estimate"] = len(_json(context).encode("utf-8"))
        if context["budget"]["input_estimate"] > 16000:
            raise DomainError("Router notice projection exceeds budget")
        schema = NoticeDecision.model_json_schema()
        messages = [
            {
                "role": "system",
                "content": _POLICY
                + " Choose silent or a concise user update for this event. Only when remaining_planning_available is present, you may choose replan_remaining to ask the Planner for a new proposal addressing the observed failure. A bounded reply must describe the needed adjustment. This cannot approve a plan/team or resume execution. For an observed completed Quest, use update_user to summarize its source-linked deliveries and artifacts. Distinguish observed evidence from Worker claims. Never invent execution.",
            },
            {"role": "user", "content": _json(context)},
        ]
        if (
            len(_json({"messages": messages, "schema": schema}).encode("utf-8"))
            + len(
                _json({"role": "system", "content": schema_format_instruction(schema)}).encode(
                    "utf-8"
                )
            )
            + 512
            > context["budget"]["effective_limit"] - self.output_reserve
        ):
            raise DomainError("Router notice context budget exceeded")
        source = "mock" if mode == "mock" else profile.structured_output_support.source
        request = ModelRequest(
            model_id=self.model_id,
            provider_id=self.provider_id,
            messages=messages,
            response_format={
                "type": "json_schema",
                "json_schema": {"name": "router_notice", "strict": True, "schema": schema},
            },
            max_output_tokens=self.output_reserve,
            context_limit=context["budget"]["effective_limit"],
            model_capabilities={"json_schema": True},
            model_capability_sources={"json_schema": source},
            budget_context=ModelCallContext(
                call_id=new_id("call"),
                purpose="router_notice",
                workspace_id=self.store.workspace.id,
                quest_id=notice["quest_id"],
            ),
        )
        response = await self.provider.generate(request)
        try:
            if (
                getattr(response, "finish_reason", None) not in {None, "stop", "mock"}
                or len(response.text.encode("utf-8")) > self.output_reserve * 8
            ):
                raise ValueError("Invalid response")
            decision = NoticeDecision.model_validate_json(response.text)
            if decision.action in {"update_user", "replan_remaining"} and (
                not decision.reply or len(decision.reply) > 10000
            ):
                raise ValueError("A bounded update is required")
            if decision.action == "replan_remaining" and not adaptive_plan:
                raise ValueError("Remaining planning is not available for this event")
            if decision.action == "silent" and decision.reply is not None:
                raise ValueError("Silent decisions cannot include a reply")
        except (TypeError, ValueError, ValidationError) as exc:
            raise DomainError("Invalid Router notice decision") from exc
        with self.store.unit_of_work() as work:
            current = work.connection.execute(
                "SELECT processed_at FROM event_inbox WHERE consumer_id='router' AND event_id=? AND notice_token=REDACTED AND notice_next_attempt>?",
                (notice["event_id"], notice_token, time.time()),
            ).fetchone()
            if current is None or current["processed_at"] is not None:
                return False
            if not self._stable_context(
                snapshot,
                self._snapshot(work.connection, notice["quest_id"] or ""),
                notice_quest=notice["quest_id"],
            ):
                return False
            if decision.action == "replan_remaining":
                if adaptive_plan != remaining_replan_context(
                    self.store, work.connection, notice["quest_id"], notice["event_id"]
                ):
                    return False
                work.append_event(
                    ForgeEvent(
                        event_type="quest.replan_requested",
                        quest_id=notice["quest_id"],
                        payload={**adaptive_plan, "adjustment_request": decision.reply},
                    )
                )
            if decision.action in {"update_user", "replan_remaining"}:
                work.add_message(
                    ConversationMessage(
                        role="assistant",
                        content=decision.reply,
                        metadata={
                            "source": "router_notice",
                            "event_id": notice["event_id"],
                            "execution_mode": "mock" if mode == "mock" else "live",
                        },
                    )
                )
            updated = work.connection.execute(
                "UPDATE router_state SET revision=revision+1 WHERE conversation_id='main' AND revision=?",
                (snapshot["state"]["revision"],),
            )
            if updated.rowcount != 1:
                raise DomainError("Router revision conflict")
            for item_id in event_ids:
                updated = work.connection.execute(
                    "UPDATE event_inbox SET processed_at=?,notice_token=NULL WHERE consumer_id='router' AND event_id=? AND processed_at IS NULL AND notice_dead_at IS NULL AND notice_token=REDACTED AND notice_next_attempt>?",
                    (now_iso(), item_id, notice_token, time.time()),
                )
                if updated.rowcount != 1:
                    raise DomainError("Router notice was already processed")
        return True

    async def handle_user_message(self, text, *, request_id=None):
        if not isinstance(text, str) or not text.strip():
            raise DomainError("Message must not be empty")
        received_at = now_iso()
        self._sync_memory()
        request_id = request_id or new_id("turn")
        if not isinstance(request_id, str) or not 1 <= len(request_id) <= 200:
            raise DomainError("Invalid request ID")

"""Opaque delivery lease, never a model-provided authorization."""

from dataclasses import dataclass
from typing import Any


@dataclass(frozen=True)
class DeliveryLease:
    consumer_id: str
    event_id: str
    seq: int
    token: str
    attempt: int


WORKER_COMMANDS = frozenset(
    {
        "worker.command.assign",
        "worker.command.cancel",
        "worker.command.pause",
        "worker.command.resume",
        "worker.command.request_status",
        "worker.command.request_revision",
    }
)
WORKER_FACTS = frozenset(
    {
        "worker.result",
        "worker.progress",
        "worker.blocked",
        "worker.failed",
        "worker.help_requested",
        "worker.artifact_ready",
        "worker.review_requested",
    }
)
URGENT_EVENTS = (
    "worker.blocked",
    "worker.failed",
    "worker.result",
    "worker.help_requested",
    "approval.requested",
    "worker.command.cancel",
)


@dataclass(frozen=True)
class EventEnvelope:
    event_id: str
    seq: int
    event_type: str
    conversation_id: str
    quest_id: str | None
    worker_id: str | None
    task_node_id: str | None
    plan_id: str | None
    task_node_key: str | None
    correlation_id: str | None
    payload: dict[str, Any]

    @classmethod
    def from_row(cls, row, payload):
        if not isinstance(payload, dict):
            raise ValueError("Invalid event payload")  # noqa: TRY004 - invalid persisted event
        node, correlation = payload.get("task_node_id"), payload.get("correlation_id")
        plan, node_key = payload.get("plan_id"), payload.get("task_node_key")
        if (
            any(
                value is not None and (not isinstance(value, str) or not value or len(value) > 256)
                for value in (node, correlation, plan, node_key)
            )
            or (node_key is not None and plan is None)
            or (
                row["event_type"] in WORKER_COMMANDS | WORKER_FACTS
                and plan is not None
                and node_key is None
            )
            or (node is not None and (plan is None or node != node_key))
        ):
            raise ValueError("Invalid event references")
        if row["event_type"] in WORKER_COMMANDS | WORKER_FACTS and (
            not row["quest_id"] or not row["worker_id"]
        ):
            raise ValueError("Worker event is missing task identity")
        return cls(
            row["event_id"],
            row["seq"],
            row["event_type"],
            row["conversation_id"],
            row["quest_id"],
            row["worker_id"],
            node,
            plan,
            node_key,
            correlation,
            payload,
        )
