            "AND json_extract(e2.payload,'$.run_id')=r.id) ORDER BY e.seq DESC LIMIT 4",
            (quest["id"], quest["plan_revision"]),
        ).fetchall()
        for row in rows:
            try:
                claim = json.loads(json.loads(row["payload"])["claim"])
