ket_file_sha256\\\": \\\"d794df820efd11166ef801d30e287a923c16c35dc9e666484be4fad6fdc9bf97\\\",\\n      \\\"numbered_content_sha256\\\": \\\"764bfd41f9ad69623a55d49eab7551bca0bb092194ff1b50286a9fcba5fec797\\\"\\n    }\\n  ],\\n  \\\"citations\\\": [\\n    {\\n      \\\"id\\\": \\\"C1\\\",\\n      \\\"source_id\\\": \\\"deepseek_intake\\\",\\n      \\\"source_sha256\\\": \\\"323aadefea69436ba23ed2de3bdbaad673d61915be9e239f3233ecf551a74179\\\",\\n      \\\"line_start\\\": 8,\\n      \\\"line_end\\\": 8,\\n      \\\"quote\\\": \\\"export type ReceiveResult = 'stored' | 'duplicate' | 'filtered'\\\",\\n      \\\"verified\\\": \\\"Single line 8 of S3 content; exact match including the semicolon-free declaration form.\\\"\\n    },\\n    {\\n      \\\"id\\\": \\\"C2\\\",\\n      \\\"source_id\\\": \\\"deepseek_intake\\\",\\n      \\\"source_sha256\\\": \\\"323aadefea69436ba23ed2de3bdbaad673d61915be9e239f3233ecf551a74179\\\",\\n      \\\"line_start\\\": 20,\\n      \\\"line_end\\\": 23,\\n      \\\"quote\\\": \\\"    // Normalize source timestamps (such as GitHub whole seconds) to canonical ISO form.\\\\n    const trigger = { ...received, at: isoTime(received.at) }\\\\n    if (!trigger.threads.length) throw new Error('A trigger must belong to at least one thread')\\\\n    if (this.repo.triggers.get(trigger.id)) return 'duplicate'\\\",\\n      \\\"verified\\\": \\\"Four contiguous lines 20-23 of S3; the leading in-range comment on line 20 is included so the quote covers the full declared range.\\\"\\n    },\\n    {\\n      \\\"id\\\": \\\"C3\\\",\\n      \\\"source_id\\\": \\\"deepseek_intake\\\",\\n      \\\"source_sha256\\\": \\\"323aadefea69436ba23ed2de3bdbaad673d61915be9e239f3233ecf551a74179\\\",\\n      \\\"line_start\\\": 25,\\n      \\\"line_end\\\": 28,\\n      \\\"quote\\\": \\\"    const filter = this.options.scope.scope(trigger)\\\\n    if (!filter.listened) {\\\\n      this.repo.triggers.save(trigger); this.repo.triggers.saveDisposition(trigger.id, { filtered: { code: filter.reason }, fanout: [], at })\\\\n      return 'filtered'\\\",\\n      \\\"verified\\\": \\\"Four contiguous lines 25-28 of S3; quote ends exactly at the return statement on line 28, matching the declared range.\\\"\\n    },\\n    {\\n      \\\"id\\\": \\\"C4\\\",\\n      \\\"source_id\\\": \\\"deepseek_intake\\\",\\n      \\\"source_sha256\\\": \\\"323aadefea69436ba23ed2de3bdbaad673d61915be9e239f3233ecf551a74179\\\",\\n      \\\"line_start\\\": 31,\\n      \\\"line_end\\\": 37,\\n      \\\"quote\\\": \\\"    const keys = trigger.threads.map(threadKey)\\\\n    // Track reached tickets and whether they were reached only via context threads (a ticket's own thread makes `context` false).\\\\n    const reached = new Map<string, { ticket: Ticket; context: boolean }>()\\\\n    for (const ref of trigger.threads) {\\\\n      const thread = this.thread(ref)\\\\n      if (!thread.lastAt || trigger.at > thread.lastAt) thread.lastAt = trigger.at\\\\n      thread.correlated = [...new Set([...thread.correlated, ...keys.filter(other => other !== thread.key)])]\\\",\\n      \\\"verified\\\": \\\"Seven contiguous lines 31-37 of S3, including the in-range comment on line 32 and the closing brace of the for-loop body on line 37.\\\"\\n    },\\n    {\\n      \\\"id\\\": \\\"C5\\\",\\n      \\\"source_id\\\": \\\"deepseek_intake\\\",\\n      \\\"source_sha256\\\": \\\"323aadefea69436ba23ed2de3bdbaad673d61915be9e239f3233ecf551a74179\\\",\\n      \\\"line_start\\\": 38,\\n      \\\"line_end\\\": 46,\\n      \\\"quote\\\": \\\"      for (const ticketId of thread.subscriptions) {\\\\n        const ticket = this.repo.tickets.get(ticketId)\\\\n        // Only a person's message on a non-context thread resumes an ended ticket; bots and CI do not (the Executor re-reads\\\\n        // threads when it resumes), and a human-stopped ticket receives nothing because its Mandate was withdrawn.\\\\n        const followed = !!thread.context?.includes(ticketId)\\\\n        const resumes = trigger.human && ticket?.ended?.by !== 'human' && !followed\\\\n        if (!ticket || (!liveTicket(ticket) && !resumes)) continue\\\\n        reached.set(ticketId, { ticket, context: followed && (reached.get(ticketId)?.context ?? true) })\\\\n      }\\\",\\n      \\\"verified\\\": \\\"Nine contiguous lines 38-46 of S3; includes both in-range comment lines 40-41 and the closing loop brace on line 46, so the quote covers the whole subscription pass-through loop.\\\"\\n    },\\n    {\\n      \\\"id\\\": \\\"C6\\\",\\n      \\\"source_id\\\": \\\"deepseek_intake\\\",\\n      \\\"source_sha256\\\": \\\"323aadefea69436ba23ed2de3bdbaad673d61915be9e239f3233ecf551a74179\\\",\\n      \\\"line_start\\\": 49,\\n      \\\"line_end\\\": 55,\\n      \\\"quote\\\": \\\"    for (const [ticketId, { ticket, context: followed }] of reached) {\\\\n      this.tickets.addInput(ticket, { id: key('input', ticketId, 'trigger', trigger.id), kind: 'trigger', triggerId: trigger.id, at,\\\\n        ...trigger.human ? { human: true } : {}, ...followed ? { context: true } : {} })\\\\n    }\\\\n    const fanout = [...reached.keys()], context = fanout.filter(id => reached.get(id)!.context)\\\\n    const disposition = { fanout, ...context.length ? { context } : {}, at }\\\\n    this.repo.triggers.saveDisposition(trigger.id, disposition)\\\",\\n      \\\"verified\\\": \\\"Seven contiguous lines 49-55 of S3; earlier revision stopped at line 54 and omitted the saveDisposition call on line 55 — now included so the quote matches the declared range.\\\"\\n    },\\n    {\\n      \\\"id\\\": \\\"C7\\\",\\n      \\\"source_id\\\": \\\"deepseek_intake\\\",\\n      \\\"source_sha256\\\": \\\"323aadefea69436ba23ed2de3bdbaad673d61915be9e239f3233ecf551a74179\\\",\\n      \\\"line_start\\\": 56,\\n      \\\"line_end\\\": 61,\\n      \\\"quote\\\": \\\"    // A person's message that no ticket decides, such as one that reached only tickets a person stopped or that follow the\\\\n    // Thread for context, and every bot's,